// Telco Customer Churn soruları (tablo: telco). IBM örnek verisi, 7.043 müşteri. Veri bilerek temizlenmedi:
// TotalCharges metin (11 satırda tek boşluk), SeniorCitizen 0/1, 'No internet service' / 'No phone service' ayrı kategori.
const TC_SORULAR = [
  // ───────── SQL · KOLAY ─────────
  { id: "tc01",
    dil: "sql",
    seviye: 1,
    kategori: "Aggregation",
    baslik: "Genel müşteri kaybı oranı",
    soru: "Toplam müşteri sayısını (<code>musteri</code>), şirketten ayrılan müşteri sayısını (<code>ayrilan</code>) ve ayrılma oranını (<code>oran</code>, %, 2 ondalık) tek satırda getir. Ayrılan müşterilerde <code>Churn</code> değeri <code>'Yes'</code>.",
    ipucu: "SQLite'ta <code>Churn = 'Yes'</code> karşılaştırması 1 ya da 0 döner. <code>SUM</code> sayıyı, <code>AVG</code> oranı verir.",
    cozum: "SELECT COUNT(*) AS musteri,\n       SUM(Churn = 'Yes') AS ayrilan,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco;",
    aciklama: "<p>Churn burada metin (<code>'Yes'</code>/<code>'No'</code>). SQLite'ta bir karşılaştırma 1 ya da 0 döndüğü için <code>SUM(Churn = 'Yes')</code> ayrılanları sayar, <code>AVG</code> da oranı verir. SQL Server'da bu kısayol yok; orada <code>SUM(CASE WHEN Churn = 'Yes' THEN 1 ELSE 0 END)</code> yazılır.</p><p>7.043 müşterinin 1.869'u, yani yaklaşık dörtte biri (%26,54) ayrılmış. Bu oran sonraki bütün soruların karşılaştırma noktası: bir grubun oranı bunun belirgin üstündeyse o grup risklidir.</p>" },
  { id: "tc02",
    dil: "sql",
    seviye: 1,
    kategori: "Aggregation",
    baslik: "Sözleşme türüne göre",
    sirali: true,
    soru: "Sözleşme türüne (<code>Contract</code>) göre müşteri sayısını (<code>musteri</code>) ve ayrılma oranını (<code>oran</code>, %, 2 ondalık) bul. Oranı yüksek olan en üstte.",
    ipucu: "<code>GROUP BY Contract</code>, oran için önceki sorudaki <code>AVG(Churn = 'Yes')</code>.",
    cozum: "SELECT Contract, COUNT(*) AS musteri, ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY Contract\nORDER BY oran DESC;",
    aciklama: "<p>Aylık sözleşmelilerin %42,71'i ayrılmış; bir yıllıklarda bu oran %11,27, iki yıllıklarda sadece %2,83. Müşteri kaybını en güçlü açıklayan değişkenlerden biri sözleşme türü.</p><p>Müşterilerin yarısından fazlası (3.875) aylık sözleşmeli ve ayrılanların %88,6'sı bu gruptan. Bir şirket için en doğrudan aksiyon da buradan çıkıyor: aylık müşterileri uzun sözleşmeye geçirmek.</p>" },
  { id: "tc03",
    dil: "sql",
    seviye: 1,
    kategori: "Temel SELECT",
    baslik: "En yüksek aylık ücret",
    sirali: true,
    soru: "Aylık ücreti (<code>MonthlyCharges</code>) en yüksek 10 müşterinin <code>customerID</code>, <code>MonthlyCharges</code>, <code>Contract</code>, <code>Churn</code> bilgilerini getir. Ücrete göre azalan, eşitlikte <code>customerID</code>'ye göre sırala.",
    ipucu: "Aynı ücreti ödeyen müşteriler var; ikinci sıralama kriteri olmadan 10. sıradaki müşteri her seferinde değişebilir.",
    cozum: "SELECT customerID, MonthlyCharges, Contract, Churn\nFROM telco\nORDER BY MonthlyCharges DESC, customerID\nLIMIT 10;",
    aciklama: "<p>118,60 ücretini iki müşteri ödüyor; <code>customerID</code> eşitliği bozmasa hangisinin önce geleceği belli olmazdı. <code>LIMIT</code> kullanırken eşitliği bozan bir sıralama kriteri eklemek iyi alışkanlık.</p><p>En pahalı 10 müşterinin 9'u bir ya da iki yıllık sözleşmeli ve 10'undan 3'ü ayrılmış. Yüksek ücret tek başına ayrılma demek değil; sözleşme türüyle birlikte bakmak gerekiyor.</p>" },
  { id: "tc04",
    dil: "sql",
    seviye: 1,
    kategori: "Aggregation",
    baslik: "İnternet hizmetine göre ücret",
    sirali: true,
    soru: "İnternet hizmeti türüne (<code>InternetService</code>) göre müşteri sayısını (<code>musteri</code>) ve ortalama aylık ücreti (<code>ort_aylik</code>, 2 ondalık) bul. Ortalama ücreti yüksek olan en üstte.",
    ipucu: "<code>ROUND(AVG(MonthlyCharges), 2)</code>",
    cozum: "SELECT InternetService, COUNT(*) AS musteri, ROUND(AVG(MonthlyCharges), 2) AS ort_aylik\nFROM telco\nGROUP BY InternetService\nORDER BY ort_aylik DESC;",
    aciklama: "<p>Fiber kullanıcıları ayda ortalama 91,50 ödüyor, DSL kullanıcıları 58,10, interneti olmayanlar 21,08. Fiber en kalabalık grup (3.096 müşteri) ve en pahalısı.</p><p><code>'No'</code> değeri bir kategori olarak duruyor: internet almayan 1.526 müşteri. Bu müşterilerin internet ek hizmeti sütunlarında da <code>'No internet service'</code> yazıyor (\"Güvenlik paketi: kategori birleştirme\" sorusu).</p>" },
  { id: "tc05",
    dil: "sql",
    seviye: 1,
    kategori: "Filtreleme",
    baslik: "Riskli profil",
    soru: "İnterneti fiber (<code>'Fiber optic'</code>), sözleşmesi aylık (<code>'Month-to-month'</code>) ve ödeme yöntemi elektronik çek (<code>'Electronic check'</code>) olan müşterilerin sayısını (<code>musteri</code>) ve ayrılma oranını (<code>oran</code>, %, 2 ondalık) bul.",
    ipucu: "Üç koşulu <code>AND</code> ile bağla. Değerlerin yazımı verideki gibi olmalı (büyük/küçük harf dahil).",
    cozum: "SELECT COUNT(*) AS musteri, ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nWHERE InternetService = 'Fiber optic'\n  AND Contract = 'Month-to-month'\n  AND PaymentMethod = 'Electronic check';",
    aciklama: "<p>Bu üç özelliği birlikte taşıyan 1.307 müşterinin %60,37'si ayrılmış, genel oranın iki katından fazla.</p><p>Bu grup müşterilerin %18,6'sı ama ayrılanların %42,2'si (789 kişi). Kampanya bütçesi kısıtlıysa önce bu gruba odaklanmak mantıklı.</p>" },
  { id: "tc06",
    dil: "sql",
    seviye: 1,
    kategori: "Aggregation",
    baslik: "Ödeme yöntemine göre",
    sirali: true,
    soru: "Ödeme yöntemine (<code>PaymentMethod</code>) göre müşteri sayısını ve ayrılma oranını (%, 2 ondalık) bul. Sütunlar: <code>PaymentMethod</code>, <code>musteri</code>, <code>oran</code>. Oranı yüksek olan en üstte.",
    ipucu: "<code>GROUP BY PaymentMethod</code>",
    cozum: "SELECT PaymentMethod, COUNT(*) AS musteri, ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY PaymentMethod\nORDER BY oran DESC;",
    aciklama: "<p>Elektronik çekle ödeyenlerde oran %45,29; otomatik ödeme (banka havalesi ya da kredi kartı) kullananlarda %15-17.</p><p>Bunu \"elektronik çek müşteriyi kaçırıyor\" diye okumamak gerekir. Elektronik çekle ödeyenlerin %78,2'si aylık sözleşmeli, otomatik ödeyenlerde bu oran %36-38. Ödeme yöntemi büyük ölçüde sözleşme etkisini taşıyor olabilir; otomatik ödemeye geçen müşteri aynı zamanda daha bağlı bir müşteri.</p>" },
  { id: "tc07",
    dil: "sql",
    seviye: 1,
    kategori: "CASE WHEN",
    baslik: "Yaşlı müşteriler",
    sirali: true,
    soru: "<code>SeniorCitizen</code> sütunu diğer evet/hayır sütunlarından farklı olarak 1/0 tutuluyor. 1'i <code>'Evet'</code>, 0'ı <code>'Hayır'</code> olarak yazan bir <code>yasli</code> sütunu oluştur; her grubun müşteri sayısını ve ayrılma oranını (%, 2 ondalık) bul. Sütunlar: <code>yasli</code>, <code>musteri</code>, <code>oran</code>. Önce Hayır, sonra Evet.",
    ipucu: "<code>CASE SeniorCitizen WHEN 1 THEN 'Evet' ELSE 'Hayır' END</code>. Sıralama için <code>ORDER BY SeniorCitizen</code>.",
    cozum: "SELECT CASE SeniorCitizen WHEN 1 THEN 'Evet' ELSE 'Hayır' END AS yasli,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY SeniorCitizen\nORDER BY SeniorCitizen;",
    aciklama: "<p>Aynı tabloda evet/hayır bilgisinin iki farklı biçimde (1/0 ve <code>'Yes'</code>/<code>'No'</code>) tutulması gerçek verilerde sık görülen bir tutarsızlık. Raporda okunur olması için etikete çevirmek gerekir.</p><p>Yaşlı müşterilerde oran %41,68, diğerlerinde %23,61. Yaşlı müşterilerin %70,7'si aylık sözleşmeli ve %72,8'i fiber kullanıyor (diğerlerinde %52 ve %38,4); yani bu fark kısmen başka risk özelliklerinden geliyor.</p>" },
  // ───────── SQL · ORTA ─────────
  { id: "tc08",
    dil: "sql",
    seviye: 2,
    kategori: "Eksik Veri",
    baslik: "Görünmeyen boşluk",
    soru: "<code>TotalCharges</code> sütunu sayı gibi görünse de metin olarak saklanıyor; bazı satırlarda değer boş değil ama içinde sadece boşluk var. Bu satırların sayısını (<code>musteri</code>), en küçük ve en büyük abonelik süresini (<code>min_tenure</code>, <code>max_tenure</code>) ve değerin karakter uzunluğunu (<code>uzunluk</code>, en küçüğü) tek satırda getir.",
    ipucu: "<code>IS NULL</code> bu satırları bulmaz. <code>TRIM(TotalCharges) = ''</code> boşlukları silip karşılaştırır; uzunluk için <code>LENGTH</code>.",
    cozum: "SELECT COUNT(*) AS musteri,\n       MIN(tenure) AS min_tenure,\n       MAX(tenure) AS max_tenure,\n       MIN(LENGTH(TotalCharges)) AS uzunluk\nFROM telco\nWHERE TRIM(TotalCharges) = '';",
    aciklama: "<p>11 müşteride <code>TotalCharges</code> tek bir boşluk karakteri (<code>' '</code>, uzunluk 1). Bu değer NULL değil, bu yüzden <code>IS NULL</code> ile ya da <code>COUNT(TotalCharges)</code> ile bulunmaz; eksik veri kontrolünde gözden kaçan klasik durum.</p><p>Bu müşterilerin hepsinin abonelik süresi 0: yeni gelmişler, henüz fatura kesilmemiş. Yani değer aslında \"bilinmiyor\" değil, 0. Bu bilgi doldurma kararını da belirliyor (\"Toplam ücreti sayıya çevir\" sorusu).</p>" },
  { id: "tc09",
    dil: "sql",
    seviye: 2,
    kategori: "Veri Kalitesi",
    baslik: "Metin olarak saklanan sayı",
    soru: "<code>TotalCharges</code>'ı 8000'den büyük olan müşterileri iki şekilde say: doğrudan <code>TotalCharges > 8000</code> ile (<code>metin_karsilastirma</code>) ve değeri sayıya çevirerek (<code>sayi_karsilastirma</code>). İki sonucu tek satırda getir.",
    ipucu: "Sayıya çevirmek için <code>CAST(TotalCharges AS REAL)</code>. İki sonuç farklı çıkıyorsa nedenini düşün.",
    cozum: "SELECT SUM(TotalCharges > 8000) AS metin_karsilastirma,\n       SUM(CAST(TotalCharges AS REAL) > 8000) AS sayi_karsilastirma\nFROM telco;",
    aciklama: "<p>Doğru cevap 78, ama doğrudan karşılaştırma 546 buluyor. Sütun metin (TEXT) olduğu için SQLite <code>8000</code>'i de metne çeviriyor ve iki metni harf harf, sözlük sırasıyla karşılaştırıyor: <code>'900' > '8000'</code> doğru, çünkü ilk karakter <code>'9'</code>, <code>'8'</code>'den büyük. 820,5 ya da 97 gibi küçük değerler bu yüzden \"8000'den büyük\" sayılıyor.</p><p>Hata vermediği için fark edilmesi en zor veri hatalarından biri. Bir sütunun türünden emin değilsen <code>typeof(sutun)</code> ile bak; sayı olması gereken metin sütunlarında karşılaştırma ve sıralamadan önce <code>CAST</code> kullan.</p>" },
  { id: "tc10",
    dil: "sql",
    seviye: 2,
    kategori: "CASE WHEN",
    baslik: "Abonelik süresine göre",
    sirali: true,
    soru: "Müşterileri abonelik süresine (<code>tenure</code>, ay) göre grupla: 12'ye kadar <code>'0-12 ay'</code>, 13-24 <code>'13-24 ay'</code>, 25-48 <code>'25-48 ay'</code>, daha uzun <code>'49+ ay'</code>. Grup başına müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>sure</code>, <code>musteri</code>, <code>oran</code>. Kısadan uzuna sırala.",
    ipucu: "CASE'teki koşullar sırayla denenir, bu yüzden üst sınırları küçükten büyüğe yazmak yeter. Sıralama için <code>ORDER BY MIN(tenure)</code>.",
    cozum: "SELECT CASE\n         WHEN tenure <= 12 THEN '0-12 ay'\n         WHEN tenure <= 24 THEN '13-24 ay'\n         WHEN tenure <= 48 THEN '25-48 ay'\n         ELSE '49+ ay'\n       END AS sure,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY sure\nORDER BY MIN(tenure);",
    aciklama: "<p>Grup etiketleri metin; <code>ORDER BY sure</code> alfabetik sıralar. Bu etiketlerde alfabetik sıra tesadüfen doğru çıkıyor, ama \"6-12 ay\" gibi bir grup eklenseydi \"49+ ay\"dan sonraya düşerdi. Her grubun en küçük <code>tenure</code>'ına göre sıralamak doğal sırayı her zaman garanti eder.</p><p>İlk yıl en kritik dönem: ilk 12 aydaki müşterilerin %47,44'ü ayrılmış, 4 yılı geçenlerde bu oran %9,51. Müşteri ne kadar kalırsa o kadar bağlanıyor; ilk 1 ayda ayrılma oranı %61,99.</p>" },
  { id: "tc11",
    dil: "sql",
    seviye: 2,
    kategori: "CASE WHEN",
    baslik: "Ek hizmet sayısı",
    sirali: true,
    soru: "İnterneti olan müşteriler için altı ek hizmetten (<code>OnlineSecurity</code>, <code>OnlineBackup</code>, <code>DeviceProtection</code>, <code>TechSupport</code>, <code>StreamingTV</code>, <code>StreamingMovies</code>) kaçını aldığını hesapla (<code>ek_hizmet</code>, 0-6). Her ek hizmet sayısı için müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>ek_hizmet</code>, <code>musteri</code>, <code>oran</code>. Ek hizmet sayısına göre sırala.",
    ipucu: "Her karşılaştırma 1/0 döndüğü için <code>(OnlineSecurity = 'Yes') + (OnlineBackup = 'Yes') + …</code> sayıyı verir. İnterneti olmayanları <code>WHERE InternetService &lt;&gt; 'No'</code> ile çıkar.",
    cozum: "SELECT (OnlineSecurity = 'Yes') + (OnlineBackup = 'Yes') + (DeviceProtection = 'Yes')\n       + (TechSupport = 'Yes') + (StreamingTV = 'Yes') + (StreamingMovies = 'Yes') AS ek_hizmet,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nWHERE InternetService <> 'No'\nGROUP BY ek_hizmet\nORDER BY ek_hizmet;",
    aciklama: "<p>Birkaç sütundan tek bir özet değişken türetmek (feature engineering) churn modellerinde çok kullanılır. Karşılaştırmaların 1/0 dönmesi, CASE yazmadan saymayı sağlıyor.</p><p>Hiç ek hizmet almayanların %52,24'ü ayrılmış, altısını da alanların %5,28'i. Her ek hizmet müşteriyi şirkete biraz daha bağlıyor gibi görünüyor; ama tersine neden de olabilir: kalmaya kararlı müşteri daha çok hizmet alıyor olabilir.</p>" },
  { id: "tc12",
    dil: "sql",
    seviye: 2,
    kategori: "Aggregation",
    baslik: "Sözleşme × internet",
    sirali: true,
    soru: "Sözleşme türü ve internet hizmeti kırılımında müşteri sayısını ve ayrılma oranını (%, 2 ondalık) bul. Sadece en az 300 müşterisi olan kombinasyonlar gelsin. Sütunlar: <code>Contract</code>, <code>InternetService</code>, <code>musteri</code>, <code>oran</code>. Oranı yüksek olan en üstte.",
    ipucu: "Gruplama sonrası filtre <code>HAVING COUNT(*) >= 300</code>.",
    cozum: "SELECT Contract, InternetService, COUNT(*) AS musteri, ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY Contract, InternetService\nHAVING COUNT(*) >= 300\nORDER BY oran DESC;",
    aciklama: "<p>Dokuz kombinasyonun hepsi 300 müşteriyi geçiyor, ama bu eşik küçük gruplarda tesadüfi yüksek oranların listenin başına çıkmasını önlemek için iyi bir alışkanlık.</p><p>Aylık sözleşmeli fiber kullanıcılarında oran %54,61; iki yıllık sözleşmeli fiber kullanıcılarında %7,23. Fiber kendi başına riskli görünse de uzun sözleşme bu riski büyük ölçüde siliyor. İki değişkene birlikte bakmak tek tek bakmaktan çok daha fazlasını söylüyor.</p>" },
  { id: "tc13",
    dil: "sql",
    seviye: 2,
    kategori: "CASE WHEN",
    baslik: "Kaybedilen aylık gelir",
    soru: "Ayrılan müşterilerin aylık ücretlerinin toplamını (<code>kayip_aylik</code>), tüm müşterilerin aylık ücret toplamını (<code>toplam_aylik</code>) ve kayıp payını (<code>kayip_oran</code>, %) bul. Hepsi 2 ondalık, tek satır.",
    ipucu: "Koşullu toplam: <code>SUM(CASE WHEN Churn = 'Yes' THEN MonthlyCharges ELSE 0 END)</code>.",
    cozum: "SELECT ROUND(SUM(CASE WHEN Churn = 'Yes' THEN MonthlyCharges ELSE 0 END), 2) AS kayip_aylik,\n       ROUND(SUM(MonthlyCharges), 2) AS toplam_aylik,\n       ROUND(100.0 * SUM(CASE WHEN Churn = 'Yes' THEN MonthlyCharges ELSE 0 END) / SUM(MonthlyCharges), 2) AS kayip_oran\nFROM telco;",
    aciklama: "<p>Müşterilerin %26,54'ü ayrılmış ama aylık gelirin %30,5'i (139.130,85) onlarla gitmiş. Ayrılanlar ortalamadan daha çok ödüyormuş.</p><p>Yönetime müşteri sayısı yerine gelir üzerinden konuşmak genelde daha etkili olur: bu tutar yıllık yaklaşık 1,67 milyon demek. Kayıp oranını adet ve tutar olarak ayrı ayrı vermek iyi bir raporlama alışkanlığı.</p>" },
  { id: "tc14",
    dil: "sql",
    seviye: 2,
    kategori: "Subquery / CTE",
    baslik: "Ortalamanın üstünde ödeyenler",
    sirali: true,
    soru: "Aylık ücreti genel ortalamanın üstünde olan müşterileri <code>'Ortalama üstü'</code>, diğerlerini <code>'Ortalama altı'</code> olarak grupla. Her grubun müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>grup</code>, <code>musteri</code>, <code>oran</code>. Grup adına göre sırala.",
    ipucu: "Genel ortalamayı bir alt sorguyla hesapla: <code>(SELECT AVG(MonthlyCharges) FROM telco)</code>.",
    cozum: "SELECT CASE WHEN MonthlyCharges > (SELECT AVG(MonthlyCharges) FROM telco)\n            THEN 'Ortalama üstü' ELSE 'Ortalama altı' END AS grup,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY grup\nORDER BY grup;",
    aciklama: "<p>Genel ortalama (64,76) tek bir değer döndüren bir alt sorgu (scalar subquery); her satırda o değerle karşılaştırılıyor. Sabit sayı yazmak yerine alt sorgu kullanmak, veri değişince sorgunun doğru kalmasını sağlar.</p><p>Ortalamanın üstünde ödeyenlerin %34,54'ü, altında ödeyenlerin %16,47'si ayrılmış. Müşterilerin çoğunluğu (3.923) ortalamanın üstünde; çünkü interneti olmayan ucuz abonelikler ortalamayı aşağı çekiyor.</p>" },
  { id: "tc15",
    dil: "sql",
    seviye: 2,
    kategori: "Veri Kalitesi",
    baslik: "Güvenlik paketi: kategori birleştirme",
    sirali: true,
    soru: "<code>OnlineSecurity</code> sütununda üç değer var: <code>'Yes'</code>, <code>'No'</code> ve interneti olmayanlar için <code>'No internet service'</code>. Son ikisini birleştirerek güvenlik paketi olanları <code>'Var'</code>, diğerlerini <code>'Yok'</code> olarak grupla. Grup başına müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>guvenlik</code>, <code>musteri</code>, <code>oran</code>. Grup adına göre sırala.",
    ipucu: "<code>CASE WHEN OnlineSecurity = 'Yes' THEN 'Var' ELSE 'Yok' END</code>",
    cozum: "SELECT CASE WHEN OnlineSecurity = 'Yes' THEN 'Var' ELSE 'Yok' END AS guvenlik,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY guvenlik\nORDER BY guvenlik;",
    aciklama: "<p>Birleştirince paketi olanlarda oran %14,61, olmayanlarda %31,33. Ama bu birleştirme bir bilgiyi saklıyor: üç değeri ayrı ayrı gruplasaydın, interneti olup paketi almayanlarda oran %41,77, interneti hiç olmayanlarda %7,4 çıkardı.</p><p>\"No internet service\" ile \"No\" aynı şey değil; biri \"hizmeti alabilir ama almamış\", diğeri \"alması mümkün değil\". Kategori birleştirirken bunun soruya uygun olup olmadığına karar vermek gerekir. Model kurarken genelde birleştirilir, çünkü internet bilgisi zaten <code>InternetService</code>'te var.</p>" },
  { id: "tc16",
    dil: "sql",
    seviye: 2,
    kategori: "Aggregation",
    baslik: "Yaş ve eş durumu",
    sirali: true,
    soru: "Yaşlılık (<code>SeniorCitizen</code> 1 ise <code>'Yaşlı'</code>, değilse <code>'Genç'</code>) ve eş durumu (<code>Partner</code>) kırılımında müşteri sayısını ve ayrılma oranını (%, 2 ondalık) bul. Sütunlar: <code>yas</code>, <code>Partner</code>, <code>musteri</code>, <code>oran</code>. Oranı yüksek olan en üstte.",
    ipucu: "<code>GROUP BY SeniorCitizen, Partner</code>; etiketi CASE ile yaz.",
    cozum: "SELECT CASE SeniorCitizen WHEN 1 THEN 'Yaşlı' ELSE 'Genç' END AS yas,\n       Partner,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM telco\nGROUP BY SeniorCitizen, Partner\nORDER BY oran DESC;",
    aciklama: "<p>En riskli grup eşi olmayan yaşlı müşteriler (%48,86), en az riskli grup eşi olan genç müşteriler (%16,65). İki etki de kendi başına var ve birbirine ekleniyor: her yaş grubunda eşi olanlar daha az ayrılıyor.</p><p>Eşi olan müşteri büyük ihtimalle bir aile aboneliğinin parçası; birden çok kişinin kullandığı bir hattı bırakmak daha zor. Bakmakla yükümlü olduğu kişi (<code>Dependents</code>) olanlarda da oran %15,45'e düşüyor.</p>" },
  // ───────── SQL · ZOR ─────────
  { id: "tc17",
    dil: "sql",
    seviye: 3,
    kategori: "Window Functions",
    baslik: "Her sözleşmede en çok ödeyen 3 müşteri",
    sirali: true,
    soru: "Her sözleşme türünde toplam ücreti (<code>TotalCharges</code>, sayıya çevirerek) en yüksek 3 müşteriyi bul. Sütunlar: <code>Contract</code>, <code>sira</code>, <code>customerID</code>, <code>toplam</code>, <code>Churn</code>. Sözleşme türüne ve sıraya göre sırala; eşitlikte <code>customerID</code>.",
    ipucu: "<code>ROW_NUMBER() OVER (PARTITION BY Contract ORDER BY CAST(TotalCharges AS REAL) DESC, customerID)</code>, sonra dışarıda <code>sira &lt;= 3</code>.",
    cozum: "WITH s AS (\n  SELECT Contract, customerID, CAST(TotalCharges AS REAL) AS toplam, Churn,\n         ROW_NUMBER() OVER (PARTITION BY Contract\n                            ORDER BY CAST(TotalCharges AS REAL) DESC, customerID) AS sira\n  FROM telco\n)\nSELECT Contract, sira, customerID, toplam, Churn\nFROM s\nWHERE sira <= 3\nORDER BY Contract, sira;",
    aciklama: "<p><code>CAST</code> unutulursa sıralama metin sırasıyla yapılır ve \"en yüksek\" diye 999,9 gibi değerler gelir (\"Metin olarak saklanan sayı\" sorusu). Window function'ın <code>WHERE</code>'de doğrudan kullanılamaması yüzünden de CTE gerekiyor.</p><p>Aylık sözleşmelilerde bile toplam ücreti 8.000'i geçen müşteri var (9481-IEBZY, 8.061,50): yıllarca aylık sözleşmeyle kalmış. Bir yıllıklarda en çok ödeyen müşteri (2889-FPWRM, 8.684,80) ayrılmış; değerli müşteri kaybının somut bir örneği.</p>" },
  { id: "tc18",
    dil: "sql",
    seviye: 3,
    kategori: "Window Functions",
    baslik: "Ayrılanlar hangi yılda gidiyor",
    sirali: true,
    soru: "Abonelik süresini yıla çevir (<code>tenure / 12</code>, tam sayı bölmesi: 0 = ilk 12 ay). Her yıl için ayrılan müşteri sayısını (<code>ayrilan</code>) ve ayrılanların o yıla kadarki kümülatif yüzdesini (<code>kumulatif_oran</code>, %, 2 ondalık) bul. Sütunlar: <code>yil</code>, <code>ayrilan</code>, <code>kumulatif_oran</code>. Yıla göre sırala.",
    ipucu: "Önce CTE'de yıla göre grupla. Sonra <code>SUM(ayrilan) OVER (ORDER BY yil)</code> kümülatif toplamı, <code>SUM(ayrilan) OVER ()</code> genel toplamı verir.",
    cozum: "WITH y AS (\n  SELECT tenure / 12 AS yil, SUM(Churn = 'Yes') AS ayrilan\n  FROM telco\n  GROUP BY yil\n)\nSELECT yil, ayrilan,\n       ROUND(100.0 * SUM(ayrilan) OVER (ORDER BY yil) / SUM(ayrilan) OVER (), 2) AS kumulatif_oran\nFROM y\nORDER BY yil;",
    aciklama: "<p>İki tamsayının bölümü SQLite'ta tamsayıdır, bu yüzden <code>tenure / 12</code> yılı doğrudan verir. Boş <code>OVER ()</code> tüm tabloyu tek pencere sayar; aynı sorguda hem kümülatif hem genel toplam almak için kullanışlı.</p><p>Ayrılanların %53,45'i ilk yılda, %80,31'i ilk üç yılda gidiyor. 6. yıl sadece <code>tenure = 72</code> olan müşterileri kapsıyor (verideki en uzun süre 72 ay), bu yüzden orada çok az kişi var.</p>" },
  { id: "tc19",
    dil: "sql",
    seviye: 3,
    kategori: "Window Functions",
    baslik: "Aylık ücret çeyrekleri",
    sirali: true,
    soru: "Müşterileri aylık ücrete göre 4 eşit gruba ayır (<code>NTILE(4)</code>, eşitlikte <code>customerID</code>). Her çeyreğin en düşük ve en yüksek aylık ücretini (<code>en_dusuk</code>, <code>en_yuksek</code>) ve ayrılma oranını (<code>oran</code>, %, 2 ondalık) bul. Sütunlar: <code>ceyrek</code>, <code>en_dusuk</code>, <code>en_yuksek</code>, <code>oran</code>. Çeyreğe göre sırala.",
    ipucu: "<code>NTILE(4) OVER (ORDER BY MonthlyCharges, customerID)</code> bir CTE'de, gruplama dışarıda.",
    cozum: "WITH c AS (\n  SELECT MonthlyCharges, Churn,\n         NTILE(4) OVER (ORDER BY MonthlyCharges, customerID) AS ceyrek\n  FROM telco\n)\nSELECT ceyrek,\n       MIN(MonthlyCharges) AS en_dusuk,\n       MAX(MonthlyCharges) AS en_yuksek,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM c\nGROUP BY ceyrek\nORDER BY ceyrek;",
    aciklama: "<p><code>NTILE</code> satırları sayıca eşit böler; aynı ücreti ödeyen müşteriler sınırda farklı çeyreklere düşebilir. 35,50 ödeyen 3 müşteri hem 1. hem 2. çeyrekte görünüyor. pandas'taki <code>qcut</code> ise değere göre böler, bu yüzden sınırları biraz farklı çıkar (\"Aylık ücret çeyrekleri\" pandas sorusu).</p><p>İlişki düz değil: oran 3. çeyreğe kadar artıyor (%37,42) ama en pahalı çeyrekte düşüyor (%32,9). En pahalı çeyrekteki müşteriler daha uzun süredir müşteri (ortalama 44,7 ay) ve daha az aylık sözleşmeli; yüksek ücret çok sayıda hizmet ve bağlılık demek.</p>" },
  { id: "tc20",
    dil: "sql",
    seviye: 3,
    kategori: "Veri Kalitesi",
    baslik: "Toplam ücret tutarlı mı",
    soru: "Toplam ücretin yaklaşık olarak aylık ücret × abonelik süresi olması beklenir. Abonelik süresi 0'dan büyük müşteriler için, <code>TotalCharges</code> (sayıya çevrilmiş) ile <code>MonthlyCharges * tenure</code> arasındaki farkı beklenen değerin %10'undan fazla olanları say. Sütunlar: <code>musteri</code> (incelenen müşteri sayısı), <code>farkli</code>, <code>farkli_oran</code> (%, 2 ondalık).",
    ipucu: "Koşul: <code>ABS(CAST(TotalCharges AS REAL) - MonthlyCharges * tenure) > 0.10 * MonthlyCharges * tenure</code>. Karşılaştırma 1/0 döndüğü için SUM ve AVG doğrudan kullanılabilir.",
    cozum: "SELECT COUNT(*) AS musteri,\n       SUM(ABS(CAST(TotalCharges AS REAL) - MonthlyCharges * tenure) > 0.10 * MonthlyCharges * tenure) AS farkli,\n       ROUND(100.0 * AVG(ABS(CAST(TotalCharges AS REAL) - MonthlyCharges * tenure) > 0.10 * MonthlyCharges * tenure), 2) AS farkli_oran\nFROM telco\nWHERE tenure > 0;",
    aciklama: "<p>İki sütun arasında beklenen bir ilişki varsa onu kontrol etmek iyi bir veri kalitesi testidir. 7.032 müşterinin 381'inde (%5,42) fark %10'u geçiyor.</p><p>Bu farklar hata olmak zorunda değil: aylık ücret bugünkü tarife, toplam ücret geçmişin toplamı. Müşteri yakın zamanda paket değiştirdiyse ikisi tutmaz. En büyük farklar kısa süreli müşterilerde: 2 aylık bir müşterinin beklenen toplamı 38,80, gerçek toplamı 61,05.</p>" },
  { id: "tc21",
    dil: "sql",
    seviye: 3,
    kategori: "Subquery / CTE",
    baslik: "Genel orandan sapma",
    sirali: true,
    soru: "Her ödeme yöntemi için ayrılma oranını (<code>oran</code>) ve bu oranın genel ayrılma oranından farkını (<code>fark</code>, yüzde puan) bul, ikisi de 2 ondalık. Genel oranı bir CTE'de hesapla. Sütunlar: <code>PaymentMethod</code>, <code>oran</code>, <code>fark</code>. Farkı büyük olan en üstte.",
    ipucu: "<code>WITH genel AS (SELECT 100.0 * AVG(Churn = 'Yes') AS oran FROM telco)</code>, sonra <code>… - (SELECT oran FROM genel)</code>.",
    cozum: "WITH genel AS (\n  SELECT 100.0 * AVG(Churn = 'Yes') AS oran FROM telco\n)\nSELECT PaymentMethod,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran,\n       ROUND(100.0 * AVG(Churn = 'Yes') - (SELECT oran FROM genel), 2) AS fark\nFROM telco\nGROUP BY PaymentMethod\nORDER BY fark DESC;",
    aciklama: "<p>Yuvarlamayı en sonda yapmak önemli: yuvarlanmış iki oranın farkını alsaydık sonuç 0,01 kayabilirdi. CTE'de yuvarlamadan tutup farkı alırken yuvarlamak doğru yol.</p><p>Elektronik çek genel oranın 18,75 puan üstünde; diğer üç yöntemin hepsi altında. \"Genel orana göre fark\" sunumlarda tek tek oranlardan daha kolay okunur: hangi grubun ortalamayı yukarı çektiği hemen görülür.</p>" },
  { id: "tc22",
    dil: "sql",
    seviye: 3,
    kategori: "Window Functions",
    baslik: "En pahalı %10 daha mı sadık",
    sirali: true,
    soru: "İnterneti olan müşterileri kendi internet hizmeti türü içinde aylık ücrete göre sırala (<code>PERCENT_RANK</code>). Sıralama değeri 0,9 ve üstü olanları <code>'En pahalı %10'</code>, diğerlerini <code>'Diğer'</code> olarak etiketle. Hizmet türü ve dilime göre müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>InternetService</code>, <code>dilim</code>, <code>musteri</code>, <code>oran</code>. Hizmet türü ve dilim adına göre sırala.",
    ipucu: "<code>PERCENT_RANK() OVER (PARTITION BY InternetService ORDER BY MonthlyCharges)</code> 0 ile 1 arasında bir değer verir.",
    cozum: "WITH r AS (\n  SELECT InternetService, Churn,\n         PERCENT_RANK() OVER (PARTITION BY InternetService ORDER BY MonthlyCharges) AS pr\n  FROM telco\n  WHERE InternetService <> 'No'\n)\nSELECT InternetService,\n       CASE WHEN pr >= 0.9 THEN 'En pahalı %10' ELSE 'Diğer' END AS dilim,\n       COUNT(*) AS musteri,\n       ROUND(100.0 * AVG(Churn = 'Yes'), 2) AS oran\nFROM r\nGROUP BY InternetService, dilim\nORDER BY InternetService, dilim;",
    aciklama: "<p><code>PARTITION BY</code> sayesinde her müşteri kendi grubundakilerle kıyaslanıyor; fiber ve DSL'in fiyatları çok farklı olduğu için genel bir sıralama anlamsız olurdu.</p><p>Her iki hizmette de en pahalı %10 çok daha az ayrılıyor: DSL'de %2,47 (diğerleri %20,8), fiberde %15,48 (diğerleri %44,83). Bu müşteriler ortalama 5,4 ek hizmet alıyor ve yaklaşık 60 aydır müşteri; çoğu iki yıllık sözleşmeli. Yüksek fatura burada memnuniyetsizlik değil, bağlılık işareti.</p>" },
  // ───────── PYTHON · KOLAY ─────────
  { id: "tc23",
    dil: "python",
    seviye: 1,
    kategori: "pandas Temelleri",
    baslik: "Churn dağılımı",
    soru: "<code>Churn</code> sütunundaki değerlerin yüzde dağılımını (2 ondalık) bul. Sonuç iki sütunlu bir tablo olsun: <code>Churn</code> ve <code>oran</code>.",
    ipucu: "<code>value_counts(normalize=True)</code> oranları verir; 100 ile çarp, <code>round(2)</code>, sonra <code>rename(\"oran\").reset_index()</code>.",
    cozum: "sonuc = (telco[\"Churn\"].value_counts(normalize=True) * 100).round(2).rename(\"oran\").reset_index()",
    aciklama: "<p><code>value_counts(normalize=True)</code> sayılar yerine oranları döndürür. Sonuç bir Series olduğu için <code>reset_index()</code> ile tabloya çeviriyoruz.</p><p>Müşterilerin %73,46'sı kalmış, %26,54'ü ayrılmış. Sınıflar dengesiz: bir model herkese \"kalacak\" dese bile %73 doğru olur. Churn modellerinde doğruluk (accuracy) yerine ayrılanları ne kadar yakaladığına bakılmasının sebebi bu.</p>" },
  { id: "tc24",
    dil: "python",
    seviye: 1,
    kategori: "Gruplama",
    baslik: "Sözleşme türüne göre ücret",
    sirali: true,
    soru: "Sözleşme türüne göre müşteri sayısını (<code>musteri</code>) ve ortalama aylık ücreti (<code>ort_aylik</code>, 2 ondalık) bul. Sütunlar: <code>Contract</code>, <code>musteri</code>, <code>ort_aylik</code>. Müşteri sayısı çok olan en üstte.",
    ipucu: "Adlandırılmış toplama: <code>.agg(musteri=(\"customerID\", \"count\"), ort_aylik=(\"MonthlyCharges\", \"mean\"))</code>.",
    cozum: "sonuc = (telco.groupby(\"Contract\")\n         .agg(musteri=(\"customerID\", \"count\"), ort_aylik=(\"MonthlyCharges\", \"mean\"))\n         .round(2)\n         .sort_values(\"musteri\", ascending=False)\n         .reset_index())",
    aciklama: "<p>Adlandırılmış toplama (<code>yeni_ad=(\"sütun\", \"fonksiyon\")</code>) hem birden çok metriği tek seferde hesaplar hem de sütunlara doğrudan istediğin adı verir.</p><p>Ortalama aylık ücret sözleşme türleri arasında çok az değişiyor (60,77 ile 66,40 arası). Yani aylık sözleşmelilerin daha çok ayrılması pahalı olmalarından değil; fark başka bir yerden geliyor.</p>" },
  { id: "tc25",
    dil: "python",
    seviye: 1,
    kategori: "Filtreleme",
    baslik: "Yeni ve aylık sözleşmeli müşteriler",
    soru: "Abonelik süresi 6 ay ya da daha kısa olan (<code>tenure &lt;= 6</code>) ve aylık sözleşmeli (<code>\"Month-to-month\"</code>) müşterileri filtrele. Müşteri sayısını (<code>musteri</code>) ve ayrılma oranını (<code>oran</code>, %, 2 ondalık) tek satırlık bir tabloda ver.",
    ipucu: "İki koşulu <code>&amp;</code> ile bağla, her koşul parantez içinde olmalı. Oran: <code>(yeni[\"Churn\"] == \"Yes\").mean()</code>. Tek satırlık tablo: <code>pd.DataFrame([{\"musteri\": …, \"oran\": …}])</code>.",
    cozum: "yeni = telco[(telco[\"tenure\"] <= 6) & (telco[\"Contract\"] == \"Month-to-month\")]\nsonuc = pd.DataFrame([{\"musteri\": len(yeni), \"oran\": round((yeni[\"Churn\"] == \"Yes\").mean() * 100, 2)}])",
    aciklama: "<p>pandas'ta koşulları birleştirirken <code>and</code> değil <code>&amp;</code> kullanılır ve her koşul parantez içine alınır; yoksa işlem önceliği yüzünden hata alırsın. Mantıksal bir Series'in ortalaması, <code>True</code> oranıdır.</p><p>İlk 6 ayındaki aylık sözleşmeli 1.413 müşterinin %55,2'si ayrılmış. Yeni müşterinin ilk aylarda ikna edilmesi (hoş geldin teklifi, uzun sözleşmeye geçiş indirimi) kaybı azaltmanın en etkili yeri.</p>" },
  { id: "tc26",
    dil: "python",
    seviye: 1,
    kategori: "Dönüşüm",
    baslik: "0/1 değerini etikete çevirme",
    soru: "<code>SeniorCitizen</code> 1/0 olarak tutuluyor. <code>map</code> ile 1'i <code>\"Evet\"</code>, 0'ı <code>\"Hayır\"</code> yapan bir <code>yasli</code> sütunu oluştur ve her grubun ayrılma oranını (%, 2 ondalık) bul. Sütunlar: <code>yasli</code>, <code>oran</code>.",
    ipucu: "<code>telco[\"SeniorCitizen\"].map({1: \"Evet\", 0: \"Hayır\"})</code>. Oran için <code>groupby(\"yasli\")[\"Churn\"]</code> üzerinde <code>(s == \"Yes\").mean()</code>.",
    cozum: "t = telco.assign(yasli=telco[\"SeniorCitizen\"].map({1: \"Evet\", 0: \"Hayır\"}))\nsonuc = (t.groupby(\"yasli\")[\"Churn\"]\n         .apply(lambda s: (s == \"Yes\").mean() * 100)\n         .round(2)\n         .rename(\"oran\")\n         .reset_index())",
    aciklama: "<p><code>map</code> sözlükte olmayan değerleri <code>NaN</code> yapar; burada sadece 0 ve 1 olduğu için sorun yok, ama kendi verinde <code>map</code> sonrası eksik değer sayısını kontrol etmek iyi alışkanlık. <code>assign</code> orijinal tabloyu değiştirmeden yeni sütunlu bir kopya döndürür.</p><p>Yaşlı müşterilerde oran %41,68, diğerlerinde %23,61.</p>" },
  { id: "tc27",
    dil: "python",
    seviye: 1,
    kategori: "pandas Temelleri",
    baslik: "Metin olarak gelen sütunlar",
    soru: "Veri türü metin (<code>object</code>) olan sütunların adlarını liste olarak bul. Hangi sütunun aslında sayı olması gerektiğini düşün.",
    ipucu: "<code>telco.select_dtypes(include=[\"object\", \"string\"]).columns.tolist()</code>",
    cozum: "sonuc = telco.select_dtypes(include=[\"object\", \"string\"]).columns.tolist()",
    aciklama: "<p>21 sütunun 18'i metin. Çoğu gerçekten kategorik (cinsiyet, sözleşme, evet/hayır sütunları) ama listede <code>TotalCharges</code> da var: toplam ücret bir sayı olmalıydı. Bir değerin bile sayıya çevrilememesi (burada 11 satırdaki boşluk) tüm sütunun metin olarak okunmasına yetiyor.</p><p>Yeni bir veriyle çalışmaya başlarken ilk bakılacak şeylerden biri <code>dtypes</code>. <code>TotalCharges.mean()</code> gibi bir işlem metin sütununda ya hata verir ya da anlamsız sonuç üretir.</p>" },
  // ───────── PYTHON · ORTA ─────────
  { id: "tc28",
    dil: "python",
    seviye: 2,
    kategori: "Eksik Veri",
    baslik: "Sayıya çevrilemeyen değerler",
    soru: "<code>TotalCharges</code> sütununda sayıya çevrilemeyen değerleri bul. Bu satırların <code>customerID</code>, <code>tenure</code>, <code>MonthlyCharges</code>, <code>TotalCharges</code> sütunlarını getir, <code>customerID</code>'ye göre sırala.",
    ipucu: "<code>pd.to_numeric(..., errors=\"coerce\")</code> çevrilemeyen değerleri <code>NaN</code> yapar; <code>.isna()</code> ile o satırları seç.",
    cozum: "sayi = pd.to_numeric(telco[\"TotalCharges\"], errors=\"coerce\")\nsonuc = (telco.loc[sayi.isna(), [\"customerID\", \"tenure\", \"MonthlyCharges\", \"TotalCharges\"]]\n         .sort_values(\"customerID\"))",
    aciklama: "<p><code>errors=\"coerce\"</code> olmadan <code>pd.to_numeric</code> ilk sorunlu değerde hata verir. Coerce ile çevrilemeyenler <code>NaN</code> olur ve hangileri olduğunu görebilirsin. <code>isna()</code> orijinal sütunda hiçbir şey bulmazdı, çünkü değerler boş değil, bir boşluk karakteri.</p><p>11 satırın hepsinde <code>tenure</code> 0: henüz ilk faturası kesilmemiş yeni müşteriler. Aylık ücretleri dolu, toplam ücretleri yok.</p>" },
  { id: "tc29",
    dil: "python",
    seviye: 2,
    kategori: "Eksik Veri",
    baslik: "Toplam ücreti sayıya çevir",
    soru: "<code>TotalCharges</code>'ı sayıya çevir; çevrilemeyen kaç değer olduğunu (<code>eksik</code>) bul. Bu değerleri 0 ile doldurup tüm müşterilerin toplam ücretlerinin toplamını (<code>toplam_gelir</code>, 2 ondalık) hesapla. Tek satırlık tablo.",
    ipucu: "<code>pd.to_numeric(..., errors=\"coerce\")</code>, sonra <code>.isna().sum()</code> ve <code>.fillna(0).sum()</code>.",
    cozum: "sayi = pd.to_numeric(telco[\"TotalCharges\"], errors=\"coerce\")\nsonuc = pd.DataFrame([{\"eksik\": int(sayi.isna().sum()), \"toplam_gelir\": round(sayi.fillna(0).sum(), 2)}])",
    aciklama: "<p>Eksik değeri neyle dolduracağın verinin anlamına bağlı. Bu 11 müşteri henüz hiç fatura ödememiş (<code>tenure</code> 0), bu yüzden 0 doğru değer. Ortalama ya da medyanla doldurmak bu müşterilere hiç ödemedikleri binlerce liralık bir geçmiş yazmak olurdu.</p><p>Toplam gelir 16.056.168,70. 0 ile doldurmak toplamı değiştirmiyor ama ortalama gibi hesaplarda bu satırların sayılmasını sağlıyor.</p>" },
  { id: "tc30",
    dil: "python",
    seviye: 2,
    kategori: "Segmentasyon",
    baslik: "Süre grupları: pd.cut",
    soru: "<code>pd.cut</code> ile abonelik süresini gruplara ayır: <code>0-12 ay</code>, <code>13-24 ay</code>, <code>25-48 ay</code>, <code>49+ ay</code>. Grup başına müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>sure</code>, <code>musteri</code>, <code>oran</code>.",
    ipucu: "<code>pd.cut(telco[\"tenure\"], bins=[-1, 12, 24, 48, 72], labels=[…])</code>. Aralıklar sağdan kapalıdır: (12, 24] = 13-24. 0'ı dahil etmek için ilk sınır -1.",
    cozum: "gruplar = pd.cut(telco[\"tenure\"], bins=[-1, 12, 24, 48, 72],\n                 labels=[\"0-12 ay\", \"13-24 ay\", \"25-48 ay\", \"49+ ay\"])\nsonuc = (telco.assign(sure=gruplar, ayrildi=telco[\"Churn\"] == \"Yes\")\n         .groupby(\"sure\", observed=True)\n         .agg(musteri=(\"customerID\", \"count\"), oran=(\"ayrildi\", \"mean\"))\n         .reset_index())\nsonuc[\"oran\"] = (sonuc[\"oran\"] * 100).round(2)",
    aciklama: "<p><code>pd.cut</code>'te aralıklar varsayılan olarak sağdan kapalıdır: <code>(-1, 12]</code> 0 ile 12'yi kapsar. İlk sınırı 0 yazsaydın <code>tenure = 0</code> olan 11 müşteri hiçbir gruba girmez, <code>NaN</code> olurdu. Kategorik sütunda gruplarken <code>observed=True</code> boş kategorilerin sonuca girmesini önler.</p><p>Sonuç SQL'deki CASE WHEN sorusuyla aynı: ilk yılda %47,44, 4 yıldan sonra %9,51.</p>" },
  { id: "tc31",
    dil: "python",
    seviye: 2,
    kategori: "Dönüşüm",
    baslik: "Ek hizmet sayısı",
    soru: "İnterneti olan müşteriler için altı ek hizmetten (<code>OnlineSecurity</code>, <code>OnlineBackup</code>, <code>DeviceProtection</code>, <code>TechSupport</code>, <code>StreamingTV</code>, <code>StreamingMovies</code>) kaç tanesinin <code>\"Yes\"</code> olduğunu sayan bir <code>ek_hizmet</code> sütunu oluştur. Her ek hizmet sayısı için ayrılma oranı (%, 2 ondalık). Sütunlar: <code>ek_hizmet</code>, <code>oran</code>.",
    ipucu: "<code>(t[hizmetler] == \"Yes\").sum(axis=1)</code> her satırdaki <code>True</code> sayısını verir.",
    cozum: "hizmetler = [\"OnlineSecurity\", \"OnlineBackup\", \"DeviceProtection\",\n             \"TechSupport\", \"StreamingTV\", \"StreamingMovies\"]\nt = telco[telco[\"InternetService\"] != \"No\"].copy()\nt[\"ek_hizmet\"] = (t[hizmetler] == \"Yes\").sum(axis=1)\nsonuc = (t.groupby(\"ek_hizmet\")[\"Churn\"]\n         .apply(lambda s: (s == \"Yes\").mean() * 100)\n         .round(2)\n         .rename(\"oran\")\n         .reset_index())",
    aciklama: "<p>Bir DataFrame'i bir değerle karşılaştırmak, aynı boyutta <code>True</code>/<code>False</code> tablosu üretir. <code>sum(axis=1)</code> satır satır toplar; döngü yazmadan altı sütunu tek satırda saymanın yolu bu.</p><p>Oran ek hizmet arttıkça düzenli şekilde düşüyor: hiç almayanlarda %52,24, altısını alanlarda %5,28.</p>" },
  { id: "tc32",
    dil: "python",
    seviye: 2,
    kategori: "Gruplama",
    baslik: "Pivot: sözleşme × internet",
    soru: "Satırlarda sözleşme türü (<code>Contract</code>), sütunlarda internet hizmeti (<code>InternetService</code>) olan bir pivot tablo oluştur. Hücrelerde ayrılma oranı (%, 1 ondalık) olsun. Sözleşme türü ilk sütun olarak dursun.",
    ipucu: "Önce 100/0 değerli bir <code>ayrildi</code> sütunu oluştur, sonra <code>pivot_table(index=\"Contract\", columns=\"InternetService\", values=\"ayrildi\", aggfunc=\"mean\")</code>.",
    cozum: "sonuc = (telco.assign(ayrildi=(telco[\"Churn\"] == \"Yes\") * 100)\n         .pivot_table(index=\"Contract\", columns=\"InternetService\",\n                      values=\"ayrildi\", aggfunc=\"mean\")\n         .round(1)\n         .reset_index())",
    aciklama: "<p>Pivot tablo iki boyutlu kırılımı tek bakışta okutur. Aynı bilgi SQL'de 9 satırlık uzun bir liste olarak gelir (\"Sözleşme × internet\" SQL sorusu).</p><p>Her satırda fiber en yüksek, her sütunda aylık sözleşme en yüksek: iki etki birbirinden bağımsız olarak var. En riskli hücre aylık sözleşmeli fiber (%54,6), en güvenli hücre interneti olmayan iki yıllık sözleşmeli müşteriler (%0,8).</p>" },
  { id: "tc33",
    dil: "python",
    seviye: 2,
    kategori: "Gruplama",
    baslik: "Çapraz tablo: ödeme yöntemi",
    soru: "Ödeme yöntemine göre kalan ve ayrılan müşterilerin satır içi yüzdesini (2 ondalık) gösteren bir çapraz tablo oluştur. Sütunlar: <code>PaymentMethod</code>, <code>No</code>, <code>Yes</code>.",
    ipucu: "<code>pd.crosstab(satır, sütun, normalize=\"index\")</code> her satırı kendi içinde %100'e tamamlar.",
    cozum: "sonuc = (pd.crosstab(telco[\"PaymentMethod\"], telco[\"Churn\"], normalize=\"index\") * 100).round(2).reset_index()",
    aciklama: "<p><code>normalize</code> parametresi neyin %100 olacağını belirler: <code>\"index\"</code> her satırı, <code>\"columns\"</code> her sütunu, <code>True</code> tüm tabloyu. \"Elektronik çekle ödeyenlerin yüzde kaçı ayrıldı?\" sorusu satır normalizasyonu ister.</p><p>Elektronik çekle ödeyenlerin %45,29'u ayrılmış; otomatik ödeme yöntemlerinde bu oran %15-17.</p>" },
  { id: "tc34",
    dil: "python",
    seviye: 2,
    kategori: "Veri Kalitesi",
    baslik: "\"Hizmet yok\" kategorilerini birleştirme",
    soru: "Altı internet ek hizmet sütununda <code>\"No internet service\"</code>, <code>MultipleLines</code>'ta <code>\"No phone service\"</code> değerlerini <code>\"No\"</code> ile değiştir. Bu yedi sütun için birleştirmeden önceki ve sonraki farklı değer sayısını gösteren bir tablo oluştur. Sütunlar: <code>sutun</code>, <code>once</code>, <code>sonra</code>.",
    ipucu: "<code>t[sutunlar].replace({\"No internet service\": \"No\", \"No phone service\": \"No\"})</code> ve <code>.nunique()</code>. İki Series'i <code>pd.DataFrame({\"once\": …, \"sonra\": …})</code> ile yan yana koy.",
    cozum: "sutunlar = [\"OnlineSecurity\", \"OnlineBackup\", \"DeviceProtection\", \"TechSupport\",\n            \"StreamingTV\", \"StreamingMovies\", \"MultipleLines\"]\nyeni = telco[sutunlar].replace({\"No internet service\": \"No\", \"No phone service\": \"No\"})\nsonuc = (pd.DataFrame({\"once\": telco[sutunlar].nunique(), \"sonra\": yeni.nunique()})\n         .rename_axis(\"sutun\")\n         .reset_index())",
    aciklama: "<p>Yedi sütunun hepsi üç değerden ikiye iniyor. Birleştirmek model kurarken yaygın bir adım: \"interneti yok\" bilgisi zaten <code>InternetService</code> sütununda var, her ek hizmet sütununda tekrar etmesine gerek yok.</p><p>Ama bu bir bilgi kaybı: \"alabilir ama almamış\" ile \"alamaz\" aynı değere düşüyor. Analizde bu iki grubun ayrılma oranları çok farklı (\"Güvenlik paketi: kategori birleştirme\" SQL sorusu). Birleştirme kararını sorunun ne olduğuna göre ver.</p>" },
  { id: "tc35",
    dil: "python",
    seviye: 2,
    kategori: "Segmentasyon",
    baslik: "Aylık ücret çeyrekleri: pd.qcut",
    soru: "<code>pd.qcut</code> ile aylık ücreti 4 çeyreğe ayır (<code>Q1</code>…<code>Q4</code>). Her çeyreğin en düşük ve en yüksek aylık ücretini ve ayrılma oranını (%, 2 ondalık) bul. Sütunlar: <code>ceyrek</code>, <code>en_dusuk</code>, <code>en_yuksek</code>, <code>oran</code>.",
    ipucu: "<code>pd.qcut(telco[\"MonthlyCharges\"], 4, labels=[\"Q1\", \"Q2\", \"Q3\", \"Q4\"])</code>, sonra <code>groupby(\"ceyrek\", observed=True).agg(...)</code>.",
    cozum: "t = telco.assign(ceyrek=pd.qcut(telco[\"MonthlyCharges\"], 4, labels=[\"Q1\", \"Q2\", \"Q3\", \"Q4\"]),\n                 ayrildi=telco[\"Churn\"] == \"Yes\")\nsonuc = (t.groupby(\"ceyrek\", observed=True)\n         .agg(en_dusuk=(\"MonthlyCharges\", \"min\"), en_yuksek=(\"MonthlyCharges\", \"max\"),\n              oran=(\"ayrildi\", \"mean\"))\n         .reset_index())\nsonuc[\"oran\"] = (sonuc[\"oran\"] * 100).round(2)",
    aciklama: "<p><code>qcut</code> sınırları değerlere göre belirler: aynı ücreti ödeyen müşteriler hep aynı çeyreğe düşer, bu yüzden çeyrekler tam eşit sayıda olmayabilir. SQL'deki <code>NTILE</code> ise satırları sayıca eşit böler ve eşit değerleri sınırda ayırabilir. İki sonuçtaki küçük farklar (Q2'nin en düşük değeri 35,55, NTILE'da 35,50) bundan.</p><p>En riskli çeyrek Q3 (%37,51), en pahalı çeyrek Q4'te oran biraz düşüyor (%32,88).</p>" },
  // ───────── PYTHON · ZOR ─────────
  { id: "tc36",
    dil: "python",
    seviye: 3,
    kategori: "Gruplama",
    baslik: "En riskli 5 segment",
    sirali: true,
    soru: "Sözleşme türü, internet hizmeti ve ödeme yöntemi kombinasyonlarında müşteri sayısını ve ayrılma oranını (%, 2 ondalık) bul. En az 100 müşterisi olan kombinasyonlardan oranı en yüksek 5 tanesini getir (eşitlikte müşteri sayısı çok olan önce). Sütunlar: <code>Contract</code>, <code>InternetService</code>, <code>PaymentMethod</code>, <code>musteri</code>, <code>oran</code>.",
    ipucu: "Üç sütunla <code>groupby</code>, <code>agg</code>, sonra <code>seg[seg[\"musteri\"] >= 100]</code>, <code>sort_values([\"oran\", \"musteri\"], ascending=[False, False]).head(5)</code>.",
    cozum: "t = telco.assign(ayrildi=telco[\"Churn\"] == \"Yes\")\nseg = (t.groupby([\"Contract\", \"InternetService\", \"PaymentMethod\"])\n         .agg(musteri=(\"customerID\", \"count\"), oran=(\"ayrildi\", \"mean\"))\n         .reset_index())\nseg[\"oran\"] = (seg[\"oran\"] * 100).round(2)\nsonuc = (seg[seg[\"musteri\"] >= 100]\n         .sort_values([\"oran\", \"musteri\"], ascending=[False, False])\n         .head(5))",
    aciklama: "<p>Üç boyutta 36 olası kombinasyon var ve bazıları çok küçük. Küçük gruplarda birkaç kişi oranı uçlara taşıyabilir; minimum grup büyüklüğü koymak segment analizinin standart adımı.</p><p>İlk dört segmentin hepsi aylık sözleşmeli fiber kullanıcıları: ödeme yöntemi ne olursa olsun oran %41'in üstünde. Zirvede elektronik çekle ödeyenler var (1.307 müşteri, %60,37). Beşinci sırada aylık sözleşmeli DSL + elektronik çek (%40,51) geliyor.</p>" },
  { id: "tc37",
    dil: "python",
    seviye: 3,
    kategori: "Veri Kalitesi",
    baslik: "Toplam ücret tutarlılığı",
    soru: "Abonelik süresi 0'dan büyük müşteriler için beklenen toplamı (<code>MonthlyCharges * tenure</code>) hesapla ve gerçek toplamla (<code>TotalCharges</code>, sayıya çevrilmiş) yüzde farkını bul: <code>(gerçek - beklenen) / beklenen * 100</code>. Tek satırlık tablo: incelenen müşteri sayısı (<code>musteri</code>), farkı %10'dan büyük olanlar (<code>fazla_10</code>), %-10'dan küçük olanlar (<code>eksik_10</code>) ve medyan fark (<code>medyan_fark</code>, 2 ondalık).",
    ipucu: "Filtreledikten sonra <code>pd.to_numeric</code> hata vermez, çünkü boşluklu satırların hepsinde <code>tenure</code> 0. Sayım için <code>(t[\"fark_yuzde\"] > 10).sum()</code>.",
    cozum: "t = telco[telco[\"tenure\"] > 0].copy()\nt[\"toplam\"] = pd.to_numeric(t[\"TotalCharges\"])\nt[\"beklenen\"] = t[\"MonthlyCharges\"] * t[\"tenure\"]\nt[\"fark_yuzde\"] = (t[\"toplam\"] - t[\"beklenen\"]) / t[\"beklenen\"] * 100\nsonuc = pd.DataFrame([{\n    \"musteri\": len(t),\n    \"fazla_10\": int((t[\"fark_yuzde\"] > 10).sum()),\n    \"eksik_10\": int((t[\"fark_yuzde\"] < -10).sum()),\n    \"medyan_fark\": round(t[\"fark_yuzde\"].median(), 2),\n}])",
    aciklama: "<p>Medyan fark 0: tipik bir müşteride toplam ücret, aylık ücret × süre ile neredeyse birebir tutuyor. Ama 7.032 müşterinin 196'sında gerçek toplam beklenenden %10'dan fazla yüksek, 185'inde %10'dan fazla düşük.</p><p>Bu farklar hata olmak zorunda değil: aylık ücret bugünkü tarife, toplam ise geçmiş faturaların toplamı. Paket yükselten müşterinin toplamı beklenenden düşük, paket düşürenin yüksek çıkar. Veri kalitesi kontrolünde amaç her farkı silmek değil, beklenen ilişkiyi bilip uçları açıklayabilmek.</p>" },
  { id: "tc38",
    dil: "python",
    seviye: 3,
    kategori: "Gruplama",
    baslik: "Ayrılanlar ve kalanlar",
    soru: "<code>TotalCharges</code>'ı sayıya çevirerek (çevrilemeyenler eksik kalsın) ayrılan ve kalan müşterilerin <code>tenure</code>, <code>MonthlyCharges</code>, <code>TotalCharges</code> ortalamalarını karşılaştır (2 ondalık). Sütunlar: <code>Churn</code>, <code>tenure</code>, <code>MonthlyCharges</code>, <code>TotalCharges</code>.",
    ipucu: "<code>telco.assign(TotalCharges=pd.to_numeric(..., errors=\"coerce\"))</code>, sonra <code>groupby(\"Churn\")[[…]].mean()</code>. <code>mean</code> eksik değerleri atlar.",
    cozum: "t = telco.assign(TotalCharges=pd.to_numeric(telco[\"TotalCharges\"], errors=\"coerce\"))\nsonuc = t.groupby(\"Churn\")[[\"tenure\", \"MonthlyCharges\", \"TotalCharges\"]].mean().round(2).reset_index()",
    aciklama: "<p>Ayrılanlar ortalama 17,98 ay kalmış, kalanlar 37,57 aydır müşteri. Ayrılanların aylık ücreti daha yüksek (74,44'e karşı 61,27) ama toplam ücretleri daha düşük (1.531,80'e karşı 2.555,34): pahalı ama kısa süreli müşteriler.</p><p><code>TotalCharges</code> çevrilmeden <code>mean()</code> çağrılsaydı pandas 2.2'de hata verirdi (metinlerin ortalaması alınamaz). <code>assign</code> aynı adla yeni sütun verince eskisinin yerine geçer, orijinal tablo değişmez.</p>" },
  { id: "tc39",
    dil: "python",
    seviye: 3,
    kategori: "NumPy",
    baslik: "Basit risk skoru",
    soru: "<code>np.where</code> ile bir risk skoru oluştur: aylık sözleşme 2 puan, fiber internet 1 puan, elektronik çek 1 puan, abonelik süresi 12 aydan kısa 1 puan (en fazla 5). Her skor için müşteri sayısı ve ayrılma oranı (%, 2 ondalık). Sütunlar: <code>risk</code>, <code>musteri</code>, <code>oran</code>.",
    ipucu: "<code>np.where(koşul, puan, 0)</code> dört kez, sonra topla. Gruplama için <code>telco.assign(risk=skor, …)</code>.",
    cozum: "skor = (np.where(telco[\"Contract\"] == \"Month-to-month\", 2, 0)\n        + np.where(telco[\"InternetService\"] == \"Fiber optic\", 1, 0)\n        + np.where(telco[\"PaymentMethod\"] == \"Electronic check\", 1, 0)\n        + np.where(telco[\"tenure\"] < 12, 1, 0))\nt = telco.assign(risk=skor, ayrildi=telco[\"Churn\"] == \"Yes\")\nsonuc = (t.groupby(\"risk\")\n         .agg(musteri=(\"customerID\", \"count\"), oran=(\"ayrildi\", \"mean\"))\n         .reset_index())\nsonuc[\"oran\"] = (sonuc[\"oran\"] * 100).round(2)",
    aciklama: "<p>Model kurmadan önce iş kurallarıyla basit bir skor yapmak hem iyi bir başlangıç çizgisidir hem de yöneticiye anlatması kolaydır. <code>np.where</code> vektörel çalışır; satır satır döngüye gerek yok.</p><p>Skor oranları çok net ayırıyor: 0 puanlı 1.830 müşterinin sadece %3,11'i, 5 puanlı 606 müşterinin %71,78'i ayrılmış. 4 ve 5 puan alan 1.888 müşteri, kampanya için hazır bir hedef listesi.</p>" },
  { id: "tc40",
    dil: "python",
    seviye: 3,
    kategori: "İstatistik",
    baslik: "Churn ile korelasyon",
    sirali: true,
    soru: "<code>tenure</code>, <code>MonthlyCharges</code>, sayıya çevrilmiş <code>TotalCharges</code> ve 1/0'a çevrilmiş Churn (<code>ayrildi</code>) sütunlarından bir tablo oluştur. Her sayısal sütunun <code>ayrildi</code> ile Pearson korelasyonunu (3 ondalık) küçükten büyüğe sırala. Sütunlar: <code>sutun</code>, <code>ayrildi</code>.",
    ipucu: "<code>t.corr()[\"ayrildi\"].drop(\"ayrildi\")</code>; sütun adı için <code>.rename_axis(\"sutun\").reset_index()</code>.",
    cozum: "t = pd.DataFrame({\n    \"tenure\": telco[\"tenure\"],\n    \"MonthlyCharges\": telco[\"MonthlyCharges\"],\n    \"TotalCharges\": pd.to_numeric(telco[\"TotalCharges\"], errors=\"coerce\"),\n    \"ayrildi\": (telco[\"Churn\"] == \"Yes\").astype(int),\n})\nsonuc = (t.corr()[\"ayrildi\"].drop(\"ayrildi\")\n         .round(3)\n         .sort_values()\n         .rename_axis(\"sutun\")\n         .reset_index())",
    aciklama: "<p>1/0 bir değişkenle Pearson korelasyonu (nokta-çift serili korelasyon) iki grup ortalaması arasındaki farkı ölçer. <code>corr()</code> eksik değerli satırları her çift için ayrı ayrı dışarıda bırakır.</p><p>En güçlü ilişki abonelik süresinde (-0,352): süre arttıkça ayrılma azalıyor. Aylık ücret pozitif (0,193), toplam ücret negatif (-0,199). Toplam ücret büyük ölçüde \"süre × aylık ücret\" olduğu için süre etkisini taşıyor; ikisini aynı modele koymak birbirine çok bağlı (çoklu doğrusal) değişkenler demek.</p>" },
  { id: "tc41",
    dil: "python",
    seviye: 3,
    kategori: "Dönüşüm",
    baslik: "Evet/hayır sütunlarını 1/0 yapma",
    sirali: true,
    soru: "Değerleri tam olarak <code>\"Yes\"</code> ve <code>\"No\"</code> olan sütunları kodla bul (elle liste yazmadan). Bu sütunları 1/0'a çevir ve her birinde \"Yes\" oranını (<code>evet_oran</code>, %, 2 ondalık) büyükten küçüğe sırala. Sütunlar: <code>sutun</code>, <code>evet_oran</code>.",
    ipucu: "<code>[c for c in telco.columns if set(telco[c].unique()) == {\"Yes\", \"No\"}]</code>, sonra <code>(telco[sutunlar] == \"Yes\").astype(int)</code>.",
    cozum: "evet_hayir = [c for c in telco.columns if set(telco[c].unique()) == {\"Yes\", \"No\"}]\nt = (telco[evet_hayir] == \"Yes\").astype(int)\nsonuc = ((t.mean() * 100).round(2)\n         .rename(\"evet_oran\")\n         .sort_values(ascending=False)\n         .rename_axis(\"sutun\")\n         .reset_index())",
    aciklama: "<p>Beş sütun bulunuyor: <code>PhoneService</code>, <code>PaperlessBilling</code>, <code>Partner</code>, <code>Dependents</code>, <code>Churn</code>. <code>MultipleLines</code> ya da <code>OnlineSecurity</code> gibi sütunlar üçüncü bir değer (\"No phone service\", \"No internet service\") taşıdığı için listeye girmiyor. <code>SeniorCitizen</code> zaten 1/0.</p><p>Sütun listesini elle yazmak yerine koşulla bulmak, veri değişince kodun doğru kalmasını sağlar. Müşterilerin %90,32'sinde telefon hizmeti var, %59,22'si kağıtsız fatura kullanıyor.</p>" },
];
if (typeof module !== 'undefined') module.exports = { TC_SORULAR };
